import React, { ReactNode, useRef } from 'react';

import { Store, createStore } from '../../../core/store/store.js';
import { CategoricalBarChartStateContext } from '../contexts/CategoricalBarChartState.context.js';
import { initialState, CategoricalBarChartState } from '../types/state.js';

export const StoreProvider = ({ children }: { children: ReactNode }) => {
  const storeRef = useRef<Store<CategoricalBarChartState>>();

  storeRef.current = createStore({
    ...initialState,
    filteredDimensions: new Set(),
    pinned: {
      ...initialState.pinned,
    },
  });

  return (
    <CategoricalBarChartStateContext.Provider value={storeRef.current}>
      {children}
    </CategoricalBarChartStateContext.Provider>
  );
};
